<?php
namespace App\Policies;use App\Domain\Tenancy\TenantContext;use App\Models\{PaymentIntentRecord,User};final class PaymentIntentRecordPolicy{private function m(User$u):bool{return$u->memberships()->where(['tenant_id'=>app(TenantContext::class)->id(),'status'=>'ACTIVE'])->exists();}public function viewAny(User$u):bool{return$this->m($u);}public function view(User$u,PaymentIntentRecord$m):bool{return$this->m($u)&&$m->tenant_id===app(TenantContext::class)->id();}public function create(User$u):bool{return$this->m($u);}public function update(User$u,PaymentIntentRecord$m):bool{return false;}public function delete(User$u,PaymentIntentRecord$m):bool{return false;}}
